bounded_host_request.command:
set -eu
umask 077
p=/home/admin1/projects/debug-ai/.worktrees/deepseek-qwen35-command-20261128
sha=1da5adfa098f8d7b45b92bb966280bcdb134d548
git -C "$p" fetch --no-tags origin "$sha"
test "$(git -C "$p" rev-parse FETCH_HEAD)" = "$sha"
tmp="$(mktemp -d)"
trap 'rm -rf -- "$tmp"' EXIT
git -C "$p" archive "$sha" server orchestrator | tar -x -C "$tmp"
chmod 755 "$tmp"
cid="$(docker ps -q --filter label=com.docker.compose.project=debug-ai --filter label=com.docker.compose.service=debug-ai)"
test -n "$cid"
image="$(docker inspect -f '{{.Image}}' "$cid")"
docker run --rm --network none --read-only --tmpfs /tmp:rw,nosuid,nodev,size=32m --cap-drop ALL --security-opt no-new-privileges --user 1000:1000 -v "$tmp/server:/app/server:ro" -v "$tmp/orchestrator:/app/orchestrator:ro" --entrypoint node "$image" --test server/tests/chat.test.cjs
if docker ps --format '{{.Names}}' | grep -Eiq 'train|distill|optimizer|lora'; then echo CHAT_LIVE_TEST_DEFERRED_TRAINING_ACTIVE; exit 0; fi
export AI_CORE_API_KEY="$(docker exec "$cid" node -e 'process.stdout.write(process.env.AI_CORE_API_KEY||"")')"
test -n "$AI_CORE_API_KEY"
docker run --rm -i --network host --read-only --tmpfs /tmp:rw,nosuid,nodev,size=32m --cap-drop ALL --security-opt no-new-privileges --user 1000:1000 -v "$tmp/server:/app/server:ro" -v "$tmp/orchestrator:/app/orchestrator:ro" -e AI_CORE_API_KEY --entrypoint node "$image" - <<'JS'
const assert=require("node:assert/strict"),http=require("node:http"),crypto=require("node:crypto"),fs=require("node:fs");
const {createAiCoreAdapter}=require("/app/server/adapters/ai-core.js");
const {createChatHandler}=require("/app/server/chat/index.js");
(async()=>{
const token=crypto.randomBytes(32).toString("hex"),root=fs.mkdtempSync("/tmp/chat-live-");
const aiCore=createAiCoreAdapter({dispatchMode:"command_only",apiKey:process.env.AI_CORE_API_KEY,commandModelGates:{qwen35:{origin:"http://127.0.0.1:18185",model_id:"/models/Qwen3.5-4B-Q4_K_M.gguf",runtime_context_tokens:8192,max_output_tokens:2048}}});
const handler=createChatHandler({aiCore,runtimeRoot:root,token});
const server=http.createServer(async(req,res)=>{if(!await handler(req,res,new URL(req.url,"http://localhost")))res.writeHead(404).end();});
await new Promise(r=>server.listen(0,"127.0.0.1",r));
const base="http://127.0.0.1:"+server.address().port,headers={authorization:"Bearer "+token,"content-type":"application/json"};
try{
assert.equal((await fetch(base+"/chat")).status,200);
assert.equal((await fetch(base+"/chat/ui.js")).status,200);
assert.equal((await fetch(base+"/chat/ui.css")).status,200);
assert.equal((await fetch(base+"/chat/api")).status,401);
let id=null;
for(const text of ["合言葉は青い月です。『了解』とだけ答えてください。","先ほどの合言葉は何でしたか？短く答えてください。"]){
const res=await fetch(base+"/chat/api",{method:"POST",headers,body:JSON.stringify({id,text,turn_id:crypto.randomUUID(),max_tokens:64})});
assert.equal(res.status,200);
const item=await res.json(),t=item.turns.at(-1);
console.log(JSON.stringify({state:t.state,error:t.error||null,actual_answer:t.answer||null,model_id:t.model_id||null,elapsed_ms:t.elapsed_ms||null,turns:item.turns.length}));
assert.equal(t.state,"complete");
assert.ok(t.answer.trim());
id=item.id;
}
const restored=await(await fetch(base+"/chat/api/"+id,{headers})).json();assert.equal(restored.turns.length,2);
assert.ok(restored.turns[1].answer.includes("青い月"),"multi-turn recall failed");
console.log("REAL_QWEN_CHAT_2_TURN_PASS");
}finally{await new Promise(r=>server.close(r));}
})().catch(e=>{console.error("CHAT_LIVE_TEST_FAILED",e.code||e.name);process.exitCode=1;});
JS
unset AI_CORE_API_KEY
